parameters.jsCode:
const data = ($input.first().json.output) || {};

// ⚠️ MULTI-TENANT: negocio al que pertenece este agente (businesses.id en MySQL)
// Restaurante Demo → REEMPLAZA el valor por su id real
const TENANT_ID = 4; // Restaurante Demo

// ── VALIDACIÓN: nunca crear un pedido sin datos completos ──
const faltantes = [];
if (!(data.nombre_cliente || '').trim()) faltantes.push('tu nombre');
if (!(data.direccion || '').trim() || data.direccion === 'No proporcionada') faltantes.push('tu dirección');
if (!data.metodo_pago) faltantes.push('el método de pago');
if (!(data.productos || []).length) faltantes.push('los productos');
if (!data.total_final || Number(data.total_final) <= 0) faltantes.push('el total');


const customer = data.nombre_cliente || 'Sin nombre';
const orderType = data.tipo_pedido || 'Domicilio';
const rawPhone = $('Mensaje Recibido').first().json.messages[0].from;
const phone = rawPhone.toString().startsWith('57') ? rawPhone : '57' + rawPhone;
const paymentMethod = data.metodo_pago || 'Efectivo';
const address = data.direccion || 'No proporcionada';
const latitude = data.latitud || 0;
const longitude = data.longitud || 0;
const shippingCost = data.costo_envio || 0;
const finalTotal = data.total_final || 0;
const products = data.productos || [];

// Texto para WhatsApp del encargado (ahora incluye notas por producto)
const orderText = products.map(p => {
  let line = `${p.nombre}${p.cantidad && p.cantidad > 1 ? ' x' + p.cantidad : ''} – $${p.precio.toLocaleString('es-CO')} COP`;
  if (p.notas && p.notas.trim() !== '') {
    line += `\n   ⚠️ _${p.notas.trim()}_`;
  }
  return line;
}).join('\n');

const order_message = `🍕 *NUEVO PEDIDO* 🍕
👤 *Cliente:* ${customer}
📞 *Teléfono:* ${phone}
🚀 *Tipo:* ${orderType}
💳 *Pago:* ${paymentMethod}
📍 *Dirección:* ${address}
📋 *PEDIDO:*
${orderText}
🛵 *Costo envío:* $${shippingCost.toLocaleString('es-CO')} COP
🧾 *TOTAL:* $${finalTotal.toLocaleString('es-CO')} COP
⏰ *Hora:* ${new Date().toLocaleString('es-CO', { timeZone: 'America/Bogota' })}
📌 *Estado:* Pendiente de confirmación`;

// Payload para el dashboard (notas incluidas en cada producto)
const dashboard_payload = {
  tenant_id: TENANT_ID,
  customer_name: customer,
  customer_phone: phone,
  order_type: orderType,
  products: products.map(p => ({
    nombre: p.nombre,
    precio: p.precio,
    cantidad: p.cantidad || 1,
    categoria: p.categoria || null,
    notas: p.notas || null
  })),
  total: finalTotal - shippingCost,
  shipping_cost: shippingCost,
  delivery_address: address === 'No proporcionada' ? null : address,
  latitude: latitude || null,
  longitude: longitude || null,
  payment_method: paymentMethod
};

if (faltantes.length > 0) {
  const mensaje = 'Para crear tu pedido necesito: ' + faltantes.join(', ') + '. ¿Me los confirmas? 😊';
  return { order_message: mensaje, dashboard_payload: null, faltantes, mensaje };
}
return { order_message, dashboard_payload, faltantes: [] };

const incomingData = $input.first().json;

const now = $now.setZone('America/Bogota');
const currentMinutes = now.hour * 60 + now.minute;

// Horario real de Restaurante Demo: todos los días de 11:00 a.m. a 9:30 p.m.
const OPEN  = 11 * 60;        // 11:00 a.m. -> 660
const CLOSE = 21 * 60 + 30;   //  9:30 p.m. -> 1290

// ⚠️ TEMPORAL (pruebas/demo): true = el bot atiende SIEMPRE, ignore el horario.
//    Cuando terminen las pruebas, ponlo en false y vuelve al horario real.
const FORZAR_ABIERTO = true;

const isOpen = FORZAR_ABIERTO || (currentMinutes >= OPEN && currentMinutes < CLOSE);
const nextOpenMsg = currentMinutes < OPEN ? 'hoy a las 11:00 a.m.' : 'mañana a las 11:00 a.m.';

incomingData.is_open = isOpen;
incomingData.next_open = nextOpenMsg;

return [{ json: incomingData }];

const items = $input.all();

if (!items[0]?.json?.fcm_token) {
  return [{ json: { skipped: true } }];
}

const fcmToken = items[0].json.fcm_token;

const serviceAccount = {
  "project_id": "tu-proyecto-demo",
  "client_email": "firebase-adminsdk@tu-proyecto.iam.gserviceaccount.com",
  "private_key": "TU_LLAVE_PRIVADA_DE_FIREBASE\n"
};

const crypto = require('crypto');
const https = require('https');

const now = Math.floor(Date.now() / 1000);
const header = Buffer.from(JSON.stringify({ alg: 'RS256', typ: 'JWT' })).toString('base64url');
const payload = Buffer.from(JSON.stringify({
  iss: serviceAccount.client_email,
  scope: 'https://www.googleapis.com/auth/firebase.messaging',
  aud: 'https://oauth2.googleapis.com/token',
  iat: now,
  exp: now + 3600
})).toString('base64url');

const sign = crypto.createSign('RSA-SHA256');
sign.update(`${header}.${payload}`);
const signature = sign.sign(serviceAccount.private_key, 'base64url');
const jwt = `${header}.${payload}.${signature}`;

const postData = `grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=${jwt}`;

const accessToken = await new Promise((resolve, reject) => {
  const req = https.request({
    hostname: 'oauth2.googleapis.com',
    path: '/token',
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Content-Length': Buffer.byteLength(postData)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => resolve(JSON.parse(data).access_token));
  });
  req.on('error', reject);
  req.write(postData);
  req.end();
});

const fcmBody = JSON.stringify({
  message: {
    token: fcmToken,
    notification: {
      title: '🔔 Nuevo pedido recibido',
      body: 'Un cliente acaba de realizar un pedido'
    },
    android: { priority: 'high' }
  }
});

const fcmResponse = await new Promise((resolve, reject) => {
  const req = https.request({
    hostname: 'fcm.googleapis.com',
    path: `/v1/projects/${serviceAccount.project_id}/messages:send`,
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(fcmBody)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => resolve(JSON.parse(data)));
  });
  req.on('error', reject);
  req.write(fcmBody);
  req.end();
});

return [{ json: { success: true, fcmResponse } }];

// Entrada: payload de Meta desde 'Mensaje Recibido'
const item = $input.first().json;
const msg = item.messages && item.messages[0];

// Si NO hay messages[] es un status (sent/delivered/read) u otro evento:
// devolvemos array vacío → la ejecución muere aquí
if (!msg || !msg.id) return [];

return [{ json: { wamid: msg.id, payload: item } }];

// Toma el payload del pedido + la respuesta de Mapbox y agrega lat/lng si faltan.
const prev = $('Formato Pedido').first().json;
const geo = $input.first().json || {};
const center = geo?.features?.[0]?.center;   // Mapbox devuelve [lng, lat]
const p = { ...prev.dashboard_payload };
if (p && !p.latitude && !p.longitude && Array.isArray(center) && center.length === 2) {
  p.latitude = center[1];
  p.longitude = center[0];
}
return [{ json: { ...prev, dashboard_payload: p } }];
